    <footer>Designed as a simple, accessible FAQ disclosure layout.</footer>

    <script>
      document.querySelectorAll('.example details').forEach((item) => {
        const summary = item.querySelector('summary');

        summary.addEventListener('keydown', (event) => {
          if (event.key === 'Escape' && item.open) {
            item.open = false;
            summary.focus();
          }
        });
      });
    </script>
